"""Base compatibility goldens and independently pinned wire-contract boundaries.

The golden was recorded before production edits, from 638af7b7f7790fc958d7bb68dd9c0643d83d2e74.
Protocol projections below are handwritten from the cited sources, not the registry.
The delete response golden was corrected with the published discriminator.
"""

from __future__ import annotations

from copy import deepcopy
import json
from pathlib import Path

import pytest
import yaml

from gateway import openai_media_schemas as schemas


def _canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8")


def test_all_base_schema_outputs_are_byte_equal():
    actual = {
        name: value for name, value in vars(schemas).items()
        if name.endswith("_OPENAPI") or name == "_ERROR_SCHEMA"
    }
    for name in (
        "_audio_speech_request_schema", "_multipart_audio_input_schema",
        "_transcription_response_schema", "_voice_entry_schema",
        "_images_generate_request_schema", "_image_object_schema",
        "_images_response_schema", "_images_edit_request_schema",
        "_audio_generate_request_schema", "_video_create_request_schema",
        "_video_create_multipart_request_schema", "_video_status_schema",
        "_video_list_response_schema", "_common_error_responses",
    ):
        actual[name] = getattr(schemas, name)()
    actual["_multipart_audio_input_schema:translation"] = schemas._multipart_audio_input_schema(translation=True)
    actual["_json_error_response"] = schemas._json_error_response("Sentinel error.")
    actual["_json_request"] = schemas._json_request({"type": "object"})
    actual["_json_request:optional"] = schemas._json_request({"type": "object"}, required=False)
    actual["_multipart_request"] = schemas._multipart_request({"type": "object"})
    assert set(actual) == set(_GOLDEN)
    for name, value in actual.items():
        assert _canonical(value) == _GOLDEN[name].encode("utf-8"), name


# Independently pinned protocol projection, retrieved 2026-11-10:
# https://raw.githubusercontent.com/openai/openai-python/v2.26.0/src/openai/types/image_edit_params.py
# https://developers.openai.com/api/reference/resources/images/methods/create_variation
# https://raw.githubusercontent.com/openai/openai-python/v2.30.0/src/openai/types/video_edit_params.py
# https://raw.githubusercontent.com/openai/openai-python/v2.30.0/src/openai/types/video_extend_params.py
# https://raw.githubusercontent.com/openai/openai-python/v2.30.0/src/openai/types/video_delete_response.py
# Only the intersection advertised by this compatibility gateway is compared.
# The upstream APIs contain additional fields and constraints; this is not a
# claim that the gateway implements the full upstream API. Known differences
# are explicit assertions below rather than a golden laundered as protocol proof.
_UPLOAD = {"type": "string", "format": "binary"}
_REFERENCE = {"type": "object", "required": ["id"], "properties": {"id": {"type": "string"}}}
_IMAGE_PROPERTIES = {
    "image": _UPLOAD, "model": {"type": "string"},
    "n": {"type": "integer", "minimum": 1, "maximum": 10},
    "size": {"type": "string"},
    "response_format": {"type": "string", "enum": ["url", "b64_json"]},
    "user": {"type": "string"},
}
_PUBLISHED_DELETE = {
    "type": "object", "required": ["id", "object", "deleted"],
    "properties": {
        "id": {"type": "string"},
        "object": {"type": "string", "enum": ["video.deleted"]},
        "deleted": {"type": "boolean"},
    },
}


def _wire(value):
    if isinstance(value, dict):
        return {key: _wire(item) for key, item in value.items() if key != "description"}
    if isinstance(value, list):
        return [_wire(item) for item in value]
    return value


def _object(required, properties):
    return {"type": "object", "required": required, "properties": properties, "additionalProperties": True}


def test_media_schema_fragments_match_pinned_wire_contract():
    edits = schemas.IMAGES_EDITS_OPENAPI["requestBody"]
    variations = schemas.IMAGES_VARIATIONS_OPENAPI["requestBody"]
    edit_video = schemas.VIDEOS_EDIT_OPENAPI["requestBody"]
    extend_video = schemas.VIDEOS_EXTEND_OPENAPI["requestBody"]
    assert set(edits["content"]) == set(variations["content"]) == {"multipart/form-data"}
    assert set(edit_video["content"]) == set(extend_video["content"]) == {"application/json", "multipart/form-data"}
    assert all(body["required"] is True for body in (edits, variations, edit_video, extend_video))
    assert _wire(variations["content"]["multipart/form-data"]["schema"]) == _object(["image"], _IMAGE_PROPERTIES)
    # Upstream image editing requires image and prompt. The unchanged gateway
    # advertises only prompt as required. Freeze the discrepancy, do not endorse it.
    expected_edit = _object(["prompt"], {**_IMAGE_PROPERTIES, "mask": _UPLOAD, "prompt": {"type": "string"}})
    assert _wire(edits["content"]["multipart/form-data"]["schema"]) == expected_edit
    assert set(expected_edit["required"]) != {"image", "prompt"}
    for body in (edit_video, extend_video):
        assert _wire(body["content"]["multipart/form-data"]["schema"]) == _object(
            ["prompt", "video"], {"prompt": {"type": "string"}, "video": _UPLOAD},
        )
    assert _wire(edit_video["content"]["application/json"]["schema"]) == _object(
        ["prompt", "video"], {"prompt": {"type": "string"}, "video": _REFERENCE},
    )
    # The gateway additionally permits numeric seconds, omits required seconds,
    # and exposes its own context_seconds. Preserve rather than silently change.
    assert _wire(extend_video["content"]["application/json"]["schema"]) == _object(
        ["prompt", "video"], {
            "prompt": {"type": "string"}, "video": _REFERENCE,
            "seconds": {"type": ["string", "number"]}, "context_seconds": {"type": "number"},
        },
    )
    deletion = schemas.VIDEOS_DELETE_OPENAPI["responses"]["200"]["content"]["application/json"]["schema"]
    assert deletion == _PUBLISHED_DELETE


def _fixture_document():
    return {"schema_version": 1, "endpoints": {"PATCH /v1/unfamiliar/{id}": {
        "requestBody": {"required": False, "content": {"application/x-unfamiliar+json": {
            "schema": _object(["novel_payload"], {"novel_payload": {"type": "string"}}),
        }}},
        "responses": {"202": {"description": "Accepted.", "content": {"application/json": {
            "schema": {"type": "object", "properties": {"accepted": {"type": "boolean"}}},
        }}}},
    }}}


def _write_document(tmp_path: Path, document):
    path = tmp_path / "fragments.yml"
    path.write_text(yaml.safe_dump(document), encoding="utf-8")
    return path


def test_unfamiliar_fragment_loads_without_python_edits(tmp_path):
    document = _fixture_document()
    fragments = schemas._load_schema_fragments(_write_document(tmp_path, document))
    actual = schemas._endpoint_fragment("PATCH", "/v1/unfamiliar/{id}", fragments=fragments)
    assert actual == document["endpoints"]["PATCH /v1/unfamiliar/{id}"]


def test_returned_fragments_are_independent(tmp_path):
    fragments = schemas._load_schema_fragments(_write_document(tmp_path, _fixture_document()))
    first = schemas._endpoint_fragment("PATCH", "/v1/unfamiliar/{id}", fragments=fragments)
    first["requestBody"]["content"].clear()
    assert schemas._endpoint_fragment("PATCH", "/v1/unfamiliar/{id}", fragments=fragments)["requestBody"]["content"]
    edited = schemas._images_edit_request_schema()
    edited["properties"].clear()
    assert schemas._images_edit_request_schema()["properties"]


@pytest.mark.parametrize("location,value", [
    (("schema_version",), True),
    (("schema_version",), 2),
    (("python_import",), "os.system"),
    (("endpoints",), []),
    (("endpoints",), {}),
    (("endpoints", "RUN /v1/odd"), {}),
    (("endpoints", "GET not-an-http-path"), {}),
    (("endpoints", "PATCH /v1/unfamiliar/{id}", "handler"), "os.system"),
    (("endpoints", "PATCH /v1/unfamiliar/{id}", "requestBody", "required"), "yes"),
    (("endpoints", "PATCH /v1/unfamiliar/{id}", "responses", "202", "python_import"), "os.system"),
    (("endpoints", "PATCH /v1/unfamiliar/{id}", "responses", "999"), {"description": "Bad", "content": {}}),
])
def test_registry_rejects_invalid_envelopes(tmp_path, location, value):
    document = _fixture_document()
    target = document
    for key in location[:-1]:
        target = target[key]
    target[location[-1]] = value
    with pytest.raises(ValueError):
        schemas._load_schema_fragments(_write_document(tmp_path, document))


@pytest.mark.parametrize("changes", [
    {"python_import": "os.system"}, {"$ref": "file:///etc/passwd"},
    {"type": "mystery"}, {"type": ["string", "string"]},
    {"required": ["absent"]}, {"required": ["novel_payload", "novel_payload"]},
    {"properties": []}, {"properties": {"novel_payload": {"type": 7}}},
    {"additionalProperties": "yes"}, {"enum": []},
    {"minimum": True}, {"format": []},
])
def test_registry_rejects_invalid_schema_keywords(tmp_path, changes):
    document = _fixture_document()
    schema = document["endpoints"]["PATCH /v1/unfamiliar/{id}"]["requestBody"]["content"]["application/x-unfamiliar+json"]["schema"]
    schema.update(changes)
    with pytest.raises(ValueError):
        schemas._load_schema_fragments(_write_document(tmp_path, document))


@pytest.mark.parametrize("text", [
    "schema_version: 1\nschema_version: 1\nendpoints: {}\n",
    "!!python/object/apply:os.system ['echo forbidden']",
    "schema_version: [unterminated",
    "schema_version: 1\nendpoints: &cycle\n  POST /v1/loop: *cycle\n",
])
def test_registry_rejects_ambiguous_or_executable_yaml(tmp_path, text):
    path = tmp_path / "fragments.yml"
    path.write_text(text, encoding="utf-8")
    with pytest.raises(ValueError):
        schemas._load_schema_fragments(path)


def test_missing_registry_is_not_silently_replaced(tmp_path):
    with pytest.raises(FileNotFoundError):
        schemas._load_schema_fragments(tmp_path / "missing.yml")


